function escapeHtml(value){return String(value ?? "").replace(/[&<>"']/g,ch=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"})[ch]);}
function cleanTopic(topic){return topic.replace(/^Unit\s*\d+\s*-\s*/i,"").trim();}
function lessonKey(){
  const direct=new URLSearchParams(location.search).get("lesson");
  if(direct && /^d[123]-\d{2}$/.test(direct)) return direct.slice(1).replace("-","-");
  let slug="";
  try{slug=new URL(document.referrer).pathname.split("/").filter(Boolean).pop()||"";}catch{}
  const mapped=SITE_MAP[slug];
  if(mapped) return mapped;
  const own=location.pathname.split("/").filter(Boolean).pop()||"";
  return SITE_MAP[own] || "1-1";
}
function findLesson(){
  const [course,number]=lessonKey().split("-").map(Number);
  const list=COURSES.find(item=>item.course===course)?.lessons||[];
  return {lesson:list.find(item=>item.number===number)||COURSES[0].lessons[0],list};
}
function youtubeEmbed(url){
  try{const parsed=new URL(url);let id="";if(parsed.hostname.includes("youtu.be"))id=parsed.pathname.slice(1);else id=parsed.searchParams.get("v")||(parsed.pathname.match(/\/embed\/([^/]+)/)?.[1]||"");return id?"https://www.youtube-nocookie.com/embed/"+id:null;}catch{return null;}
}
function taskFor(lesson,list){
  if(lesson.homework)return {nextTheory:null,...lesson.homework};
  const index=list.findIndex(item=>item.number===lesson.number);
  const nextTheory=list.slice(index+1).find(item=>item.type==="theory")||null;
  if(lesson.type==="theory") return {nextTheory,title:'Ôn bài và học từ mới của chủ đề “'+cleanTopic(lesson.topic)+'”',items:["Ôn lại nội dung bài học trên slide.","Tra cứu thêm từ điển, thuộc nghĩa và hiểu cách sử dụng của các từ mới đã được học."]};
  if(lesson.type==="writing") return {nextTheory,title:"Sử dụng Grammarly để sửa First Draft và hoàn thành Second Draft",items:["Mở Grammarly theo nút hướng dẫn bên dưới, sau đó nhập hoặc dán nguyên văn First Draft đã hoàn thành trên lớp.","Đọc từng gợi ý và phần giải thích lỗi; chỉ chọn Accept khi em hiểu và thấy gợi ý không làm thay đổi ý muốn nói.","Sau khi sửa xong, đọc lại toàn bài rồi viết Second Draft hoàn chỉnh vào Vở Writing Debate Book; viết sạch, rõ và không dùng bút chì."]};
  const nextTopic=nextTheory?cleanTopic(nextTheory.topic):(lesson.course===1&&lesson.number===48?"Is Homework Helpful?":null);
  return {nextTheory,title:nextTopic?'Chuẩn bị chủ đề tiếp theo: “'+nextTopic+'”':"Tổng kết buổi tranh biện",items:nextTopic?['Đọc trước chủ đề “'+nextTopic+'” trong sách để chuẩn bị cho buổi tranh biện kế tiếp.',"Xem các video bổ trợ bên dưới với phụ đề tiếng Anh; không sử dụng phụ đề tiếng Việt.","Nếu video nhanh, đặt tốc độ 0.75×; ghi lại từ mới và những ý tưởng có thể dùng cho chủ đề mới."]:["Xem lại slide Debate Day và ghi lại một luận điểm mạnh của mình.","Ghi lại một điểm cần cải thiện về lập luận, phát âm hoặc cách trình bày."]};
}
function videoHtml(url,index){
  const embed=youtubeEmbed(url);
  if(embed)return '<article class="video-card"><iframe loading="lazy" src="'+escapeHtml(embed)+'" title="Video bổ trợ '+(index+1)+'" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowfullscreen></iframe><div><span>VIDEO '+String(index+1).padStart(2,"0")+'</span><a href="'+escapeHtml(url)+'" target="_blank" rel="noreferrer">Mở trên YouTube ↗</a></div></article>';
  return '<a class="external-video" href="'+escapeHtml(url)+'" target="_blank" rel="noreferrer"><span>VIDEO '+String(index+1).padStart(2,"0")+'</span><strong>Nguồn học bổ trợ</strong><small>Mở nội dung ở trang gốc ↗</small></a>';
}
function revisionHtml(){return '<section class="revision-section"><div class="section-heading"><p class="overline">HƯỚNG DẪN NHANH</p><h2>Cách dùng Grammarly để sửa bài</h2><p>Làm lần lượt theo ba bước dưới đây. Grammarly là công cụ hỗ trợ; em phải đọc và hiểu từng gợi ý trước khi sửa.</p><a class="grammarly-action" href="https://app.grammarly.com/" target="_blank" rel="noreferrer">Mở Grammarly ↗</a></div><div class="revision-grid"><article class="revision-card"><span>BƯỚC 01</span><h3>Nhập First Draft</h3><label><input type="checkbox"> Mở Grammarly và chọn tạo tài liệu mới.</label><label><input type="checkbox"> Nhập hoặc dán đúng nguyên văn First Draft.</label><label><input type="checkbox"> Đọc lại để bảo đảm không thiếu câu hoặc sai nội dung.</label></article><article class="revision-card"><span>BƯỚC 02</span><h3>Hiểu rồi mới sửa</h3><label><input type="checkbox"> Bấm vào từng từ hoặc câu được gạch chân.</label><label><input type="checkbox"> Đọc kỹ lỗi và phần giải thích của Grammarly.</label><label><input type="checkbox"> Chọn Accept khi đã hiểu và đồng ý với cách sửa.</label><label><input type="checkbox"> Bỏ qua gợi ý không phù hợp hoặc làm thay đổi ý muốn nói.</label></article><article class="revision-card"><span>BƯỚC 03</span><h3>Hoàn thành Second Draft</h3><label><input type="checkbox"> Đọc lại toàn bộ bài sau khi sửa.</label><label><input type="checkbox"> Kiểm tra để quan điểm và ví dụ vẫn đúng ý ban đầu.</label><label><input type="checkbox"> Viết lại toàn bộ Second Draft vào vở, sạch và rõ.</label><label><input type="checkbox"> Không viết bút chì và nộp vở vào buổi học kế tiếp.</label></article></div><div class="grammarly-note"><strong>Lưu ý:</strong> Không chọn Accept All. Grammarly hỗ trợ phát hiện lỗi ngôn ngữ nhưng không thay em quyết định nội dung và lập luận.</div></section>';}
function render(){
  const {lesson,list}=findLesson();
  const meta={theory:{vi:"Bài học lý thuyết",en:"LEARN",step:"01"},writing:{vi:"Buổi viết bài",en:"WRITE",step:"02"},debate:{vi:"Buổi tranh biện",en:"DEBATE",step:"03"}}[lesson.type];
  const task=taskFor(lesson,list);
  const slide='https://docs.google.com/presentation/d/'+lesson.slideId+'/embed?start=false&loop=false&delayms=3000';
  const videos=lesson.videos.length?'<section class="video-section"><div class="section-heading"><p class="overline">03 · VIDEO BỔ TRỢ</p><h2>'+(lesson.type==="debate"&&task.nextTheory?"Chuẩn bị cho chủ đề tiếp theo":"Mở rộng ý tưởng và từ vựng")+'</h2><p>Ưu tiên nghe hiểu ý chính trước, sau đó xem lại với phụ đề tiếng Anh.</p></div><div class="video-grid">'+lesson.videos.map(videoHtml).join("")+'</div></section>':"";
  document.title='Debate '+lesson.course+' · Buổi '+String(lesson.number).padStart(2,"0")+' | Ms. Trang Trieu Education';
  document.getElementById("app").innerHTML='<main class="site-shell lesson-page lesson-'+lesson.type+'"><header class="brand-bar lesson-brand"><div class="brand-link"><img src="./ms-trang-trieu-education-logo.png" alt="Ms. Trang Trieu Education"><div><p class="brand-kicker">DEBATE '+lesson.course+'</p></div></div><div class="lesson-code">BUỔI '+String(lesson.number).padStart(2,"0")+'</div></header><section class="lesson-hero"><div class="lesson-number">'+meta.step+'</div><div><p class="overline">UNIT '+String(lesson.unit).padStart(2,"0")+' · '+meta.en+'</p><h1>'+escapeHtml(lesson.topic)+'</h1><p class="lesson-subtitle">'+meta.vi+' · Buổi học số '+String(lesson.number).padStart(2,"0")+'</p></div></section><section class="slide-section"><div class="section-heading inline-heading"><div><p class="overline">01 · BÀI GIẢNG GỐC</p><h2>Ôn tập lại bài học trên lớp qua slide sau:</h2></div><a href="'+escapeHtml(lesson.slideUrl)+'" target="_blank" rel="noreferrer" class="text-link">Mở slide ở tab mới ↗</a></div><div class="slide-frame"><iframe src="'+escapeHtml(slide)+'" title="Slide Debate '+lesson.course+' - Buổi '+lesson.number+'" allowfullscreen></iframe></div></section><section class="task-section"><div class="task-label"><span>02</span><p>NHIỆM VỤ SAU BUỔI HỌC</p></div><div class="task-copy"><h2>'+escapeHtml(task.title)+'</h2><ol>'+task.items.map(item=>'<li>'+escapeHtml(item)+'</li>').join("")+'</ol><div class="deadline">Hoàn thành trước buổi học tiếp theo.</div></div></section>'+videos+(lesson.type==="writing"?revisionHtml():"")+'<footer class="site-footer">MS. TRANG TRIEU EDUCATION · DEBATE '+lesson.course+'</footer></main>';
}
render();
